/// Returns the root entity of the window, if it has one.
pub fn root<E>(&self) -> Option<Option<Entity<E>>>
where
    E: 'static + Render,
{
    self.root
        .as_ref()
        .map(|view| view.clone().downcast::<E>().ok())
